calls = []

@task
def sq(x):
    calls.append(x)
    return x * x

@entrypoint(checkpointer=InMemorySaver())
def wf(nums: list, *, previous=None):
    futs = [sq(n) for n in nums]
    total = sum(f.result() for f in futs)
    return (previous or 0) + total

cfg = {"configurable": {"thread_id": "t"}}
print(wf.invoke([1, 2, 3], cfg), wf.invoke([1], cfg), sorted(calls))
```
